  // ================================================================ opening
  opening() { const c = this.g.camp!; c.started = true; if (this.ch) this.ways(this.ch); this.s.onCue({ k: 'title', text: this.m.title }); const h = this.s.R.heroes().map(i => this.g.chars[i].name); void this.tell('opening', this.ch?.read ?? this.m.pitch, this.facts()); if (this.ch?.goal) this.later(1500, () => this.s.beat('sys', this.ch!.goal, { icon: 'scroll-quill' })); void h; this.later(2500, () => { for (const i of this.s.R.heroes()) { const r = this.s.room(i); if (r) { this.d.enterRoom(i, r); break } } }) }
