  private nap(b: Block) { this.snooze.set(this.id(b), Date.now() + 40000); if (b.sel === 'start') this.near.delete(this.id(b)) }
  private mark(b: Block) { this.st.done[this.id(b)] = 1; this.d.touch(); this.s.onDirty() }
  private finish(b: Block, id: string, o?: Out) { this.mark(b); if (o) this.apply(o, id, b) }
  /** a spoken answer to a riddle */
  solve(id: string, text: string): boolean { const S = this.scene; if (!S || S.kind !== 'puzzle') return false; const b = this.block(S.key)!; const t = text.toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim(); if (!t) return false; this.s.beat('do', `“${text.trim()}”`, { who: this.s.R.name(id), color: this.s.host.color(id) }); const A = b.answers ?? []; if (A.some(a => a === t || (` ${t} `.includes(` ${a} `) && t.split(' ').length <= a.split(' ').length + 4))) { this.close(); this.finish(b, id, b.win); return true } S.tries = (S.tries ?? 0) + 1; if (b.wrong) this.apply(b.wrong, id, b); else this.s.beat('read', 'Nothing happens.'); if (S.tries >= 5 && b.lose) { this.close(); this.finish(b, id, b.lose) } else this.pub(); return true }
  // ================================================================ fights
  fight(b: Block) { const ps = this.ps; let ids = (ps.foes[b.key + b.ch] ?? []).filter(i => this.s.R.alive(i)); if (!ids.length && !(ps.foes[b.key + b.ch]?.length)) { const h = this.s.R.up()[0]; const p = h ? this.s.env.pos(h)! : undefined; ids = this.bring(b, false, p && isP(ps.bind[b.sel]) ? this.s.spotNear({ x: p.x + 6, y: p.y, z: p.z + 2 }, 4) : undefined); if (!ids.length && p) ids = this.bring(b, false, this.s.spotNear({ x: p.x + 4, y: p.y, z: p.z + 2 }, 3)); if (!ids.length) { this.finish(b, h ?? '', b.win ?? { text: '', fx: [] }); return } } for (const i of ids) { const t = this.s.w.tokens.get(i); if (t?.hidden) this.s.put([{ ...t, hidden: false }]); this.g.mons[i].side = 'foe'; this.s.syncToken(i) } if (ids.length) this.s.engage(ids, { surprise: b.flags.includes('ambush') ? this.seen(ids) : null, label: this.g.mons[ids[0]]?.boss ? this.g.mons[ids[0]].name : '' }) }
  /** who spots an ambush */
  private seen(ids: string[]): 'heroes' | null { const st = Math.max(...ids.map(i => 10 + (monster(this.g.mons[i].ref)?.stealth ?? 0))); return this.s.R.up().some(h => this.s.R.pp(h) >= st) ? null : 'heroes' }
  checkWon(b: Block) { const ids = this.ps.foes[b.key + b.ch]; if (!ids?.length || this.isDone(b)) return; if (ids.some(i => this.g.mons[i] && this.s.R.alive(i) && this.g.mons[i].side === 'foe')) return; if (this.scene?.key === this.id(b)) this.close(); this.finish(b, this.s.R.up()[0] ?? '', b.win ?? { text: '', fx: [] }) }
  fightEnd() { for (const c of this.m.chapters) if (c.n - 1 === this.st.ch) for (const b of c.blocks) if ((b.kind === 'fight' || b.kind === 'boss') && b.place === this.st.place) this.checkWon(b) }
  // ================================================================ what follows
  apply(o: Out, id: string, b?: Block) { if (o.text) void this.tell('outcome', this.fmt(o.text, id), `${o.text}`); for (const f of o.fx) try { this.fx(f, id, b) } catch (e) { console.error('campaign effect', f, e) } this.s.syncTokens(); if (!this.scene) this.sync(); this.s.onDirty() }
