export function asHero(spec: string, seed: string) { const k = spec + seed; let h = AS.get(k); if (!h) { const [cls, rc, sex] = spec.split(':'); const r = makeRng(k); const R = race(rc ?? 'human'); const d = defaultDraft(cls as any, R.id); d.looks = { ...d.looks, sex: sex === 'f' ? 'f' : 'm', skin: r.pick(R.skins), hair: r.pick(R.hairs), head: Math.floor(r() * 5), cloth: r.pick(['#5b3a2e', '#3c4f3a', '#39465f', '#6b5836', '#59324a', '#2f4f4f', '#6a2e2a', '#4a4a52']), gear: r() < .45 }; h = makeHero({ ...d, name: 'x' }); AS.set(k, h) } return h }
export { MONSTERS, RACES, SKILL_NAME, type Mon }
